{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "This review included randomized controlled trials and non-randomized intervention studies, which might provide evidence on the effects of interventions that cannot be randomized or adequately studied in randomized trials ( 19 ). We included studies only if they were conducted in low- and middle-income countries, as defined by the World Bank ( 21 ). We excluded nonintervention studies, such as case series, case reports, and qualitative studies, and those conducted in high-income countries from this review.",
      "reason": "Eligibility-related study characteristics are specified for study design and setting (LMICs vs high-income) and exclusion of nonintervention designs, but follow-up requirements (and full set of question-framework components) are not clearly reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "We selected only peerreviewed journal articles and reports from international organizations as publication types. We included studies in any language if they had English abstracts.",
      "reason": "Report characteristics used for eligibility are specified, including publication type (peer-reviewed journal articles and international organization reports) and language (any language with English abstracts)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The publication period was set to 2000-2015 to ensure that enough studies were retrieved.",
      "reason": "A publication/dissemination time window (2000–2015) is explicitly stated as part of the eligibility/search parameters."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe how the review distinguishes exclusions where outcomes were not measured versus outcomes/results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "We analyzed the results only narratively because the outcome measurements and interventions differed among the selected studies. First, we summarized the included study interventions according to the related NCDs, settings, study design, participants, intervention components, outcomes, and quantitative results. Second, we stratified the studies according to the NCD type integrated with RMNCH care and provided narrative descriptions for each NCD type.",
      "reason": "The synthesis groupings are specified in terms of stratification by NCD type integrated with RMNCH care, but the retrieved evidence does not show that these groups are explicitly linked to the specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "We excluded studies that were conducted specifically in populations with an underlying disease or condition, such as in HIV-positive women, which would complicate the generalizability of our findings to a wider population.",
      "reason": "A rationale is provided for at least one notable eligibility restriction (excluding populations with underlying conditions to preserve generalizability), but the retrieved evidence does not provide rationales for other notable restrictions (e.g., LMIC-only, English abstracts requirement) consistently."
    }
  ],
  "confidence": 62
}

